package com.clinica.backend.controller;
import com.clinica.backend.dto.*; import com.clinica.backend.service.ClinicService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/appointments") public class AppointmentController{private final ClinicService clinic;public AppointmentController(ClinicService c){clinic=c;}@GetMapping public List<AppointmentResponse> list(){return clinic.allAppointments();}@GetMapping("/my") public List<AppointmentResponse> mine(Authentication a){return clinic.myAppointments(a.getName());}@PostMapping @ResponseStatus(HttpStatus.CREATED) public AppointmentResponse create(@Valid @RequestBody AppointmentRequest r){return clinic.createAppointment(r);}}
